import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const importer = fileURLToPath(import.meta.url);
const load = createRequire(import.meta.url);
const here = dirname(importer);

// Looks for a prebuilt addon in each packaging location.
export function probeAddon(name) {
  const codes = [];
  const dirs = [join(here, "prebuilds", `${process.platform}-${process.arch}`), join(here, "native"), here];
  for (const dir of dirs) {
    try {
      const addon = load(join(dir, `${name}.node`));
      return `loaded ${typeof addon}`;
    } catch (error) {
      codes.push(error.code);
    }
  }
  return `absent: ${codes.join(", ")}`;
}

function describe(spec) {
  try {
    load(spec);
    return "loaded";
  } catch (error) {
    return `${error.name} ${error.code}: ${error.message.replaceAll(importer, "<importer>")}`;
  }
}

export function requireErrors() {
  const specs = [
    "./missing.js",
    "./missing",
    "../missing-directory/",
    "scriptc-corpus-missing-package",
    "@scriptc-corpus/missing/sub",
    "node:not-a-builtin",
    "",
    42,
    undefined,
  ];
  return specs.map((spec) => `${typeof spec === "string" ? JSON.stringify(spec) : String(spec)} -> ${describe(spec)}`);
}
